arguments:
{"script":"p=$(sed -n '1p' temp_workspace_check/candidates.txt)
if [ -n "$p" ]; then
  if [ -L "$p" ]; then echo "symlink:$p";
  elif [ -f "$p" ]; then echo "regular file:$p";
  elif [ -d "$p" ]; then echo "directory:$p";
  else echo "other:$p"; fi > temp_workspace_check/typed_candidates.txt
  grep -F 'regular file:' temp_workspace_check/typed_candidates.txt | sed 's/^regular file://' | sort -u > temp_workspace_check/regular_matches.txt
fi
wc -l temp_workspace_check/regular_matches.txt 2>/dev/null || true"}
